// crates/kanban-tui/src/handlers/board_handlers.rs

/// Precondition + open the tiered confirm dialog. Empty vs non-empty is
/// reflected in the rendered message; the actual empty/cascade branch is
/// decided inside `cascade::delete_board`.
pub fn handle_delete_board_key(&mut self) {
    if self.focus.active == Focus::Boards {
        if let Some(idx) = self.selection.board.get() {
            if self.model.boards().get(idx).is_some() {
                self.open_dialog(DialogMode::DeleteBoardConfirm);
            }
        }
    }
}

pub fn handle_delete_board_confirm_popup(&mut self, key_code: KeyCode) {
    match key_code {
        KeyCode::Enter | KeyCode::Char('y') | KeyCode::Char('Y') => {
            self.delete_board();
            self.pop_mode();
        }
        KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => self.pop_mode(),
        _ => {}
    }
}

pub fn delete_board(&mut self) {
    let Some(idx) = self.selection.board.get() else { return };
    let Some(board_id) = self.model.boards().get(idx).map(|b| b.id) else { return };
    let remaining_after = self.model.boards().len().saturating_sub(1);

    if let Err(e) = self.ctx.delete_board(board_id) {
        tracing::error!("Failed to delete board: {}", e);
        self.set_error(format!("Failed to delete board: {}", e));
        return;
    }
    tracing::info!("Deleted board {}", board_id);

    // Board-selection fixup: clamp to the surviving range or clear.
    if remaining_after == 0 {
        self.selection.board.clear();
        self.selection.active_board_index = None;
    } else {
        let new_idx = idx.min(remaining_after - 1);
        self.selection.board.set(Some(new_idx));
        self.selection.active_board_index = Some(new_idx);
    }
    self.switch_view_strategy(kanban_domain::TaskListView::default());
}
```

A small count helper for the render (pure, testable):

```rust
/// (columns, live cards, archived cards, sprints) owned by `board_id`.
pub(crate) fn board_delete_counts(&self, board_id: uuid::Uuid) -> (usize, usize, usize, usize) {
    let col_ids: std::collections::HashSet<uuid::Uuid> = self
        .model.columns().iter()
        .filter(|c| c.board_id == board_id).map(|c| c.id).collect();
    let columns = col_ids.len();
    let cards = self.model.cards().iter().filter(|c| col_ids.contains(&c.column_id)).count();
    let archived = self.model.archived_cards().iter()
        .filter(|a| col_ids.contains(&a.original_column_id)).count();
    let sprints = self.model.sprints().iter().filter(|s| s.board_id == board_id).count();
    (columns, cards, archived, sprints)
}
```

Real tiered render:

```rust
// crates/kanban-tui/src/ui/dialogs/boards.rs
pub(crate) fn render_delete_board_confirm_popup(app: &App, frame: &mut Frame) {
    let area = centered_rect(60, 40, frame.area());
    frame.render_widget(Clear, area);
    let block = Block::default().title("Delete Project")
        .borders(Borders::ALL).style(Style::default().bg(Color::Black));
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let counts = app.selection.board.get()
        .and_then(|i| app.model.boards().get(i))
        .map(|b| app.board_delete_counts(b.id));

    let body = match counts {
        Some((0, 0, 0, 0)) | None =>
            "This project is empty.\nDelete it permanently?".to_string(),
        Some((cols, cards, archived, sprints)) => format!(
            "Permanently delete this project and everything in it?\n\
             {cols} column(s), {cards} task(s), {archived} archived task(s), {sprints} sprint(s)\n\
             This can be undone with `u`.",
        ),
    };
    let chunks = Layout::default().direction(Direction::Vertical).margin(2)
        .constraints([Constraint::Min(0), Constraint::Length(1)]).split(inner);
    frame.render_widget(Paragraph::new(body).style(Style::default().fg(Color::Yellow)), chunks[0]);
    frame.render_widget(
        Paragraph::new("Press ENTER/y to delete, n/ESC to cancel").style(label_text()),
        chunks[1],
    );
}
```

