```rust
// crates/kanban-domain/src/data_store.rs  (DataStore trait, archived-card section)
/// Board-scoped archived cards. Default filters the full list by the
/// `board_id` field now carried on each ArchivedCard (B1). SQL backends
/// override with a single `WHERE board_id = ?` query.
fn list_archived_cards_by_board(&self, board_id: Uuid) -> KanbanResult<Vec<ArchivedCard>> {
    Ok(self
        .list_archived_cards()?
        .into_iter()
        .filter(|ac| ac.board_id == board_id)
        .collect())
}
```

```rust
// crates/kanban-domain/src/in_memory_store/archived_cards.rs
pub(super) fn list_archived_cards_by_board_impl(
    &self,
    board_id: Uuid,
) -> KanbanResult<Vec<ArchivedCard>> {
    let state = self.read_state()?;
    let mut acs: Vec<ArchivedCard> = state
        .archived_cards
        .values()
        .filter(|ac| ac.board_id == board_id)
        .cloned()
        .collect();
    acs.sort_by(|a, b| a.archived_at.cmp(&b.archived_at));
    Ok(acs)
}
// + trait method in in_memory_store/mod.rs delegating to the _impl
```

