    Some(bid) => self.list_archived_cards_by_board(bid)?,   // was: list_archived_cards() + column post-filter
    None => self.list_archived_cards()?,
};
let board = match filter.board_id {
    Some(bid) => self.get_board(bid)?,
    None => None,
};
