Transform sketch (`v7_to_v8_archived_cards.rs`, modelled on `transform_v6_to_v7_value`):
```rust
pub(crate) fn transform_v7_to_v8_value(envelope: &mut Value) -> PersistenceResult<()> {
    if envelope.get("version").and_then(|v| v.as_u64()).unwrap_or(0) >= 8 {
        return Ok(());
    }
    let data = envelope.get_mut("data").and_then(|d| d.as_object_mut());
    if let Some(data) = data {
        // column_id -> board_id
        let col_to_board: HashMap<String, Value> = data
            .get("columns").and_then(|c| c.as_array()).into_iter().flatten()
            .filter_map(|c| Some((c.get("id")?.as_str()?.to_string(), c.get("board_id")?.clone())))
            .collect();
        // archived id set, and board_id backfill
        let mut archived_ids = std::collections::HashSet::new();
        if let Some(acs) = data.get_mut("archived_cards").and_then(|a| a.as_array_mut()) {
            for ac in acs.iter_mut() {
                if let Some(id) = ac.get("card").and_then(|c| c.get("id")).and_then(|v| v.as_str()) {
                    archived_ids.insert(id.to_string());
                }
                if ac.get("board_id").is_none() {
                    let bid = ac.get("original_column_id").and_then(|v| v.as_str())
                        .and_then(|c| col_to_board.get(c)).cloned()
                        .unwrap_or_else(|| Value::String(uuid::Uuid::nil().to_string()));
                    ac.as_object_mut().unwrap().insert("board_id".into(), bid);
                }
            }
        }
        // defensive: drop any live-cards entry shadowing an archived card
        if let Some(cards) = data.get_mut("cards").and_then(|c| c.as_array_mut()) {
            cards.retain(|c| c.get("id").and_then(|v| v.as_str())
                .map(|id| !archived_ids.contains(id)).unwrap_or(true));
        }
    }
    envelope["version"] = Value::Number(8.into());
    Ok(())
}
```

