use crate::dependencies::{DependencyError, messages};

/// Builds a user-facing hint string for an `Add*` edge error.
/// Returns the message verbatim; callers wrap it into their layer's
/// error type (`KanbanCliError::Resolution`, `McpError::Resolution`, etc.).
pub fn add_error_hint(
    err: &DependencyError,
    parent_raw: &str,
    child_raw: &str,
) -> String {
    match err {
        DependencyError::CycleDetected => messages::parent_cycle(parent_raw, child_raw),
        DependencyError::SelfReference => messages::parent_self_reference(parent_raw),
        DependencyError::DuplicateEdge => messages::parent_duplicate(parent_raw, child_raw),
        DependencyError::NotFound => messages::parent_edge_not_found(parent_raw, child_raw),
        // ... cover every variant exhaustively
