// kanban-service/src/file_backend.rs
pub(crate) enum FileBackendInner { Json(JsonDataStore), Sqlite(SqliteBackend) }
pub struct FileBackend(FileBackendInner);

impl FileBackend {
    pub async fn open(path: &str, registry: &StoreRegistry) -> KanbanResult<Self> {
        if SqliteStoreFactory.matches_content(&read_header(path)?) {
            return Ok(FileBackend(FileBackendInner::Sqlite(SqliteBackend::open(path).await?)));
        }
        let store = registry.create_store('json', path)?;
        Ok(FileBackend(FileBackendInner::Json(JsonDataStore::new(store))))
    }
}
// Implement DataStore, CommandStore, KanbanBackend, Flushable by delegating to inner variant
