    /// additive: pre-V9 files gain an empty array; board markers default null.
    V9,
}
impl FormatVersion {
    pub const MAX: Self = Self::V9;
    pub fn as_u32(self) -> u32 { /* ..., Self::V8 => 8, Self::V9 => 9 */ }
