New transform `crates/kanban-persistence-json/src/migration/v8_to_v9_archived_boards.rs`:
```rust
use kanban_persistence::{PersistenceError, PersistenceResult};
use serde_json::Value;
use std::path::Path;

/// Pure transform: ensure `data.archived_boards` exists as an array and bump
/// the envelope to version 9. Idempotent on `version >= 9`. Purely additive —
/// no board record is read or rewritten (the `archived_at` marker defaults via
/// BoardHelper's serde default), so it never loses data.
pub(crate) fn transform_v8_to_v9_value(envelope: &mut Value) -> PersistenceResult<()> {
    if envelope.get("version").and_then(|v| v.as_u64()).unwrap_or(0) >= 9 {
        return Ok(());
    }
    if let Some(data) = envelope.get_mut("data").and_then(|d| d.as_object_mut()) {
        data.entry("archived_boards").or_insert_with(|| Value::Array(vec![]));
    }
    envelope["version"] = Value::Number(9.into());
    Ok(())
}

/// Async file wrapper: read → transform → atomic write. Output is V9.
pub(crate) async fn migrate_v8_to_v9(path: &Path) -> PersistenceResult<()> {
    let content = tokio::fs::read_to_string(path).await?;
    let mut envelope: Value = serde_json::from_str(&content)
        .map_err(|e| PersistenceError::Serialization(e.to_string()))?;
    transform_v8_to_v9_value(&mut envelope)?;
    let json_str = serde_json::to_string_pretty(&envelope)
        .map_err(|e| PersistenceError::Serialization(e.to_string()))?;
    crate::atomic_writer::AtomicWriter::write_atomic(path, json_str.as_bytes()).await?;
    Ok(())
}
```
Backup arm (`backup.rs`, extending B3's `pre_latest_backup_path_for`):
