```rust
impl KanbanContext {
    pub fn archive_board(&mut self, id: Uuid) -> KanbanResult<()> {
        if self.backend.get_board(id)?.is_none() { return Err(KanbanError::not_found("Board", id)); }
        self.execute(vec![Command::Board(BoardCommand::ArchiveBoard(ArchiveBoard { board_id: id }))])
    }
    pub fn restore_board(&mut self, id: Uuid) -> KanbanResult<Board> {
        if self.backend.get_board(id)?.is_none() { return Err(KanbanError::not_found("Board", id)); }
        self.execute(vec![Command::Board(BoardCommand::RestoreBoard(RestoreBoard { board_id: id }))])?;
        self.get_board_impl(id)?.ok_or_else(|| KanbanError::not_found("Board", id))
    }
    pub fn list_archived_boards(&self) -> KanbanResult<Vec<ArchivedBoardSummary>> {
        Ok(self.backend.list_archived_boards()?.iter().map(ArchivedBoardSummary::from).collect())
    }
    pub fn permanently_delete_archived_board(&mut self, id: Uuid) -> KanbanResult<()> {
        let board = self.backend.get_board(id)?.ok_or_else(|| KanbanError::not_found("Board", id))?;
        if !board.is_archived() {
            return Err(KanbanError::validation("board must be archived before permanent deletion"));
        }
        let commands = crate::cascade::delete_board(self.backend.as_data_store(), id)?;
        self.execute(commands)
    }
}
```
