### 3. `list_live_cards` helper — DEFINE here, CONSUME in C3b
```rust
impl KanbanContext {
    /// All LIVE cards: list_all_cards minus cards whose column belongs to an archived board.
    /// Bounded cost of the marker design (D3). Fast-path when nothing is archived.
    /// Defined here; the audit that repoints EXCLUDE call sites onto it is C3b.
    pub(super) fn list_live_cards(&self) -> KanbanResult<Vec<Card>> {
        let archived_board_ids: HashSet<Uuid> =
            self.backend.list_archived_boards()?.iter().map(|b| b.id).collect();
        if archived_board_ids.is_empty() { return self.backend.list_all_cards(); }
        let archived_col_ids: HashSet<Uuid> = self.backend.list_all_columns()?
            .into_iter().filter(|c| archived_board_ids.contains(&c.board_id)).map(|c| c.id).collect();
        Ok(self.backend.list_all_cards()?.into_iter()
            .filter(|c| !archived_col_ids.contains(&c.column_id)).collect())
    }
}
```

