/// Archive the selected live board (reversible). Boards-focus only.
pub fn handle_archive_board(&mut self) {
    if self.focus.active != Focus::Boards {
        return;
    }
    let Some(idx) = self.selection.board.get() else { return };
    let Some(board_id) = self.model.boards().get(idx).map(|b| b.id) else { return };
    let remaining_after = self.model.boards().len().saturating_sub(1);
    if let Err(e) = self.ctx.archive_board(board_id) {
        tracing::error!("Failed to archive board: {}", e);
        self.set_error(format!("Failed to archive board: {}", e));
        return;
    }
    tracing::info!("Archived board {}", board_id);
    self.fixup_board_selection_after_removal(idx, remaining_after);
}

/// Enter / leave the Archived Projects view (mirror handle_toggle_archived_cards_view).
pub fn handle_toggle_archived_boards_view(&mut self) {
    match self.mode {
        AppMode::Normal if self.focus.active == Focus::Boards => {
            self.mode = AppMode::ArchivedBoardsView;
            self.selection.archived_board = if self.model.archived_boards().is_empty() {
                None
            } else {
                Some(0)
            };
            self.needs_redraw = true;
        }
        AppMode::ArchivedBoardsView => {
            self.mode = AppMode::Normal;
            self.needs_redraw = true;
        }
        _ => {}
    }
}

/// Restore the selected archived board losslessly (ArchivedBoardsView only).
pub fn handle_restore_board(&mut self) {
    if self.mode != AppMode::ArchivedBoardsView {
        return;
    }
    let Some(idx) = self.selection.archived_board else { return };
    let Some(board_id) = self.model.archived_boards().get(idx).map(|b| b.id) else { return };
    if let Err(e) = self.ctx.restore_board(board_id) {
        self.set_error(format!("Failed to restore project: {}", e));
        return;
    }
    self.clamp_archived_board_selection();
}

/// Open the permanent-delete confirm (destructive; ArchivedBoardsView only).
pub fn handle_delete_archived_board_key(&mut self) {
    if self.mode == AppMode::ArchivedBoardsView && self.selection.archived_board.is_some() {
        self.open_dialog(DialogMode::DeleteArchivedBoardConfirm);
    }
}

pub fn handle_delete_archived_board_confirm_popup(&mut self, key_code: KeyCode) {
    match key_code {
        KeyCode::Enter | KeyCode::Char('y') | KeyCode::Char('Y') => {
            self.delete_archived_board();
            self.pop_mode();
        }
        KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => self.pop_mode(),
        _ => {}
    }
}

pub fn delete_archived_board(&mut self) {
    let Some(idx) = self.selection.archived_board else { return };
    let Some(board_id) = self.model.archived_boards().get(idx).map(|b| b.id) else { return };
    if let Err(e) = self.ctx.delete_archived_board(board_id) {
        self.set_error(format!("Failed to delete archived project: {}", e));
        return;
    }
    self.clamp_archived_board_selection();
}
