Handler arms (`crates/kanban-cli/src/handlers/board.rs`, in `handle`):

```rust
BoardAction::Archive { board } => {
    let uuid = match ctx.resolve_board_id(&board) {
        Ok(u) => u,
        Err(e) => return output::output_error(&e.to_string()),
    };
    ctx.archive_board(uuid)?;
    ctx.save().await?;
    output::output_success(serde_json::json!({"archived": uuid.to_string()}));
}
BoardAction::Restore { board } => {
    let uuid = match ctx.resolve_archived_board_id(&board) {
        Ok(u) => u,
        Err(e) => return output::output_error(&e.to_string()),
    };
    let restored = ctx.restore_board(uuid)?;
    ctx.save().await?;
    output::output_success(BoardResponse::from(&restored));
}
BoardAction::ListArchived { page, page_size } => {
    let archived = ctx.list_archived_boards()?;
    let responses: Vec<ArchivedBoardResponse> =
        archived.iter().map(ArchivedBoardResponse::from).collect();
    let (page, page_size) = resolve_page_params(page, page_size)?;
    output::output_success(PaginatedList::paginate(responses, page, page_size)?);
}
BoardAction::DeleteArchived { board } => {
    let uuid = match ctx.resolve_archived_board_id(&board) {
        Ok(u) => u,
        Err(e) => return output::output_error(&e.to_string()),
    };
    ctx.delete_archived_board(uuid)?;
    ctx.save().await?;
    output::output_success(serde_json::json!({"deleted": uuid.to_string()}));
}
```

